return {api_version=1,id="EX1_594",name="Vaporize",text="<b>Secret:</b> When a minion attacks your hero, destroy it.",set="EXPERT1",type="spell",class="mage",rarity="rare",spell_school="fire",cost=3,keywords={"secret"},triggers={{event="attack",timing="before",active_zones={"secret"},condition=function(ctx,self,e)return e.defender==ctx:player(ctx:controller(self)).hero and ctx:entity(e.attacker).type=="minion"end,effect=function(ctx,self,e)ctx:reveal_secret(self);cardlib.effects.destroy(ctx, e.attacker)end}}}
